output_text:
[
  {
    "id": "checkout_cart_at_bay",
    "text": "At the beginning of a shopping trip, the shopper is obliged to take the available cart from the cart bay before continuing.",
    "abstraction": {
      "state_properties": {
        "at_cart_bay_with_cart": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "checkout_cart": {
          "pre": {
            "and": [
              "at_cart_bay_with_cart",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "checkout_cart"
    }
  },
  {
    "id": "no_depart_bay_without_cart",
    "text": "A shopper standing at the cart bay with an available cart is prohibited from moving away while leaving that cart behind.",
    "abstraction": {
      "state_properties": {
        "at_unclaimed_cart": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "depart_unclaimed_cart": {
          "pre": {
            "and": [
              "at_unclaimed_cart",
              "MOVE"
            ]
          },
          "post": "cartAt(1,5)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "depart_unclaimed_cart"
    }
  },
  {
    "id": "items_only_into_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying merchandise by hand rather than placing it in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "take_item_by_hand": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "leave_cart_only_at_corral",
    "text": "A cart may only be left at the designated cart-return corral at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "at_cart_return_corral": "at(0,1)",
        "away_from_cart_return_corral": {
          "not": "at_cart_return_corral"
        }
      },
      "events": {
        "abandon_cart_outside_corral": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_cart_return_corral"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandon_cart_outside_corral"
    }
  },
  {
    "id": "return_checked_out_cart",
    "text": "After checking out a cart, the shopper is obliged to return it to the cart-return corral before the trip ends.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_corral": "at(0,1)",
        "holding_cart_at_corral": {
          "and": [
            "hasCart",
            "at_cart_return_corral"
          ]
        }
      },
      "events": {
        "checkout_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_corral": {
          "pre": {
            "and": [
              "holding_cart_at_corral",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "checkout_cart",
      "discharge": "return_cart_to_corral"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from exiting the store while still holding or pushing a shopping cart.",
    "abstraction": {
      "state_properties": {
        "has_active_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "has_active_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_cart_in_restricted_egg_aisle",
    "text": "A shopper pushing a cart is prohibited from taking it east or south from the egg shelf into the restricted exit-side aisle.",
    "abstraction": {
      "state_properties": {
        "at_egg_shelf_position": "at(6,4)",
        "cart_in_restricted_aisle": {
          "and": [
            "hasCart",
            {
              "or": [
                "at(7,4)",
                "at(8,4)"
              ]
            }
          ]
        }
      },
      "events": {
        "drive_cart_east_from_egg_shelf": {
          "pre": {
            "and": [
              "at_egg_shelf_position",
              "hasCart",
              "E"
            ]
          },
          "post": null
        },
        "drive_cart_south_from_egg_shelf": {
          "pre": {
            "and": [
              "at_egg_shelf_position",
              "hasCart",
              "S"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "drive_cart_east_from_egg_shelf",
          "drive_cart_south_from_egg_shelf",
          "cart_in_restricted_aisle"
        ]
      }
    }
  }
]
